# Above the Venusian Clouds - setup: factions, hulls, rooms, interiors and fleet ladders.
#
# Everything is `venus_`-prefixed: every public function in a mastlib .py becomes a MAST
# global in one flat namespace, so an unprefixed name collides with anything else loaded.
#
# The data here is GENERATED by _tools/build_mod.py (never hand-edited): venus_manifest.json,
# the .grid interiors and the *_fleets.json ladders in this mastlib, and venus_ships.json in
# the media pack.

VENUS_ADDON = "venus_fleets"
VENUS_PROBE_KEY = "venus_steam_cruiser"
VENUS_LIFT_ROOM = "lift-ring"

_venus_manifest_cache = {}


def venus_manifest():
    """The generated manifest: factions, per-hull points (rings, emitters, turret mounts),
    clouds, interiors and ladders. Read once per mission from the mastlib."""
    if "m" not in _venus_manifest_cache:
        from sbs_utils.procedural.media import media_read_relative_file
        from sbs_utils.fs import load_json_string
        _venus_manifest_cache["m"] = load_json_string(media_read_relative_file("venus_manifest.json")) or {}
    return _venus_manifest_cache["m"]


def venus_manifest_reset():
    """Forget the cached manifest (mission reload)."""
    _venus_manifest_cache.clear()


def venus_hull_info(key_or_obj):
    """The manifest entry for a hull key or a spawned object, or None."""
    key = key_or_obj
    if not isinstance(key, str):
        try:
            key = key_or_obj.art_id
        except AttributeError:
            try:
                from sbs_utils.procedural.query import to_object
                key = to_object(key_or_obj).art_id
            except Exception:
                return None
    return (venus_manifest().get("hulls") or {}).get(key)


def venus_faction_info(race):
    return (venus_manifest().get("factions") or {}).get(race)


def venus_races():
    """The six faction (race) names, in manifest order."""
    return list((venus_manifest().get("factions") or {}).keys())


def venus_register_races():
    """ADD the six factions to PLAYABLE_RACES and NPC_RACES, keeping what is there.

    `settings_add_defaults` only fills missing keys, so it cannot append; the live dict
    from `settings_get_defaults()` is edited in place instead. Must run before anything
    reads those settings.
    """
    from sbs_utils.procedural.settings import settings_get_defaults
    settings = settings_get_defaults()
    added = []
    for key in ("PLAYABLE_RACES", "NPC_RACES"):
        raw = settings.get(key) or ""
        if not isinstance(raw, str):
            raw = ",".join(str(x) for x in raw)
        have = {r.strip().lower() for r in raw.split(",") if r.strip()}
        new = [r for r in venus_races() if r.lower() not in have]
        if new:
            settings[key] = (raw + ", " if raw.strip() else "") + ", ".join(new)
            added += [key + ":" + r for r in new]
    return added


def venus_register_rooms():
    """The lift-ring room: the system the whole mod turns on. Registered here, in the
    mod, never in the library's table or a grid theme."""
    from sbs_utils.procedural.grid_rooms import grid_room_register
    grid_room_register(VENUS_LIFT_ROOM, "system,lift")


def venus_safe_status(text):
    """A status string MAST can assign: no braces (MAST f-string-formats assigned strings)."""
    text = str(text).replace("{", "(").replace("}", ")")
    return text if len(text) <= 300 else text[:297] + "..."


def venus_declare_ships():
    """Give every hull to the engine and the library - through `add_extra`, which records
    the file so `sim_create()` can replay it after `create_new_sim()` wipes the engine's
    table. Raw `sbs.add_extra_ship_data` is never replayed; three mods lost every hull that
    way. Returns a status string, not a dict (see venus_safe_status)."""
    from sbs_utils.procedural.ship_data import add_extra, get_ship_data_for
    reached = add_extra("venus_ships", mod=VENUS_ADDON)
    have = get_ship_data_for(VENUS_PROBE_KEY) is not None
    return venus_safe_status("engine=" + str(reached) + " library=" + ("ok" if have else "MISSING"))


def venus_hull_count():
    """Hulls the LIBRARY can see with our prefix - the test range asserts it equals the
    manifest's count (not double: a merge that is not replace-by-key doubles on run 2)."""
    from sbs_utils.procedural.ship_data import get_ship_data
    n = 0
    data = get_ship_data() or {}
    ships = data.get("#ship-list", []) if hasattr(data, "get") else data
    for e in ships or []:
        k = e.get("key") if hasattr(e, "get") else getattr(e, "key", None)
        if str(k or "").startswith("venus_"):
            n += 1
    return n


def _venus_enabled(kind):
    from sbs_utils.procedural.settings import settings_race_is_playable, settings_race_is_npc
    check = settings_race_is_playable if kind == "interiors" else settings_race_is_npc
    section = venus_manifest().get(kind) or {}
    return [race for race in section if check(race)]


def venus_load_interiors():
    """Merge the .grid interiors of every PLAYABLE faction. Returns how many loaded."""
    from sbs_utils.procedural.media import media_read_relative_file
    from sbs_utils.procedural.grid import grid_merge_ascii
    n = 0
    for race in _venus_enabled("interiors"):
        for plan in venus_manifest()["interiors"][race]:
            grid_merge_ascii(media_read_relative_file(plan), VENUS_ADDON)
            n += 1
    return n


def venus_load_ladders():
    """Register the JSON fleet ladder of every NPC faction. JSON, not YAML: the library's
    fleet_table_register takes the parsed table, so the mod parses its own JSON."""
    from sbs_utils.procedural.media import media_read_relative_file
    from sbs_utils.procedural.fleet_tables import fleet_table_register
    from sbs_utils.fs import load_json_string
    n = 0
    for race in _venus_enabled("fleets"):
        data = load_json_string(media_read_relative_file(venus_manifest()["fleets"][race])) or {}
        if fleet_table_register(data.get("race", race), data.get("fleets"), VENUS_ADDON):
            n += 1
    return n
